 final class FixtureBank implements EconomyAdapter{final Map<UUID,Double> money=new ConcurrentHashMap<>();int debits,credits;UUID lose,reject,unknownCredit;public String name(){return "CallerNativeFixture";}public boolean add(Account a,double n){if(SuiteState.held())throw new AssertionError("gateway refund held Suite");credits++;if(a.getUUID().equals(unknownCredit)){unknownCredit=null;throw new IllegalStateException("explicit uncertain credit without effect");}money.merge(a.getUUID(),n,Double::sum);return true;}public boolean subtract(Account a,double n){if(SuiteState.held())throw new AssertionError("gateway debit held Suite");debits++;if(a.getUUID().equals(reject)){reject=null;return false;}money.merge(a.getUUID(),-n,Double::sum);if(a.getUUID().equals(lose)){lose=null;throw new IllegalStateException("explicit lost fixture response");}return true;}public boolean hasAccount(Account a){return true;}public double getBalance(Account a){return money.getOrDefault(a.getUUID(),0D);}public void newAccount(Account a){}public void deleteAccount(Account a){}public boolean renameAccount(Account a,String n){return true;}public boolean setBalance(Account a,double n){money.put(a.getUUID(),n);return true;}public String getFormattedBalance(double n){return Double.toString(n);}}
